-- weapon_balance_core.lua: the damage-per-second factors of the weapon styles (owner debug item 47: "Fórmula de dano
-- das armas muito inconsistente"; server/data/spells/README.md "Weapon damage per second"). Pure Lua, no engine calls;
-- tests/weapon_balance_test.lua. weapon_styles.lua applies it to every weapon hit.
--
-- weapon_balance_config.lua (generated by server/tools/weapon_sim.py --write) holds, at a list of character levels, the
-- factor a two-handed melee weapon, a bow and a crossbow multiply their hit by so that the style deals the damage per
-- second of its target against one hand + a shield (two-handed melee and crossbow 1.04, bow 1.00 and its splash), at the
-- attack and attack interval the equipment of that level has. Between two levels the factor is linear, below the first
-- and above the last it is flat. typeFactor scales a weapon type (sword, axe, club) whose base items are off the tier.
-- Lua 5.1 / LuaJIT and 5.3.

ChaosWeaponBalance = ChaosWeaponBalance or {}
local W = ChaosWeaponBalance

if not W.config then
	W.config = dofile("data/scripts/chaos/weapon_balance_config.lua")
end

-- linear interpolation over levels / values, flat outside
function W.interp(levels, values, level)
	level = tonumber(level) or 0
	if level <= levels[1] then
		return values[1]
	end
	for i = 2, #levels do
		if level <= levels[i] then
			local x0, x1 = levels[i - 1], levels[i]
			return values[i - 1] + (values[i] - values[i - 1]) * (level - x0) / (x1 - x0)
		end
	end
	return values[#values]
end

-- style: "twoHanded" (a two-handed sword, axe or club), "bow" or "crossbow"; anything else (one-handed) is 1
function W.factor(style, level)
	local values = W.config[style]
	if not values then
		return 1
	end
	return W.interp(W.config.levels, values, level)
end

-- weaponType: "sword", "club", "axe" (a melee weapon; anything else is 1)
function W.typeFactor(weaponType)
	return W.config.typeFactor[weaponType] or 1
end

-- the factor of a hit: twoHanded / launcherKind as weapon_styles.lua knows the weapon in the hands
-- (launcherKind "bow" or "crossbow" for a launcher, else nil), weaponType the items.xml type name of a melee weapon
function W.hitFactor(level, twoHanded, launcherKind, weaponType)
	if launcherKind then
		return W.factor(launcherKind, level)
	end
	if twoHanded then
		return W.factor("twoHanded", level) * W.typeFactor(weaponType)
	end
	return W.typeFactor(weaponType)
end

return W
